{"query": "WITH all_detected AS (
  SELECT "Gene" AS g FROM proteinatlas WHERE "RNA tissue distribution"='Detected in all' AND "RNA tissue specificity"='Tissue enriched' LIMIT 5
)
SELECT "Gene name", Tissue, nTPM FROM rna_tissue_consensus 
WHERE "Gene name" IN (SELECT g FROM all_detected)
ORDER BY "Gene name", TRY_CAST(nTPM AS DOUBLE) ASC"}
